/* ================= PROMPT CONTEXT ================= */
const RUBRIC='Six-item structure rubric, one point each (0–6): (1) answers the question asked — names the case type, top of tree is the client objective in its units; (2) two to four buckets, MECE at the top level; (3) smells like the industry — the first click-down under each bucket only applies to this business; (4) each bucket goes one level down with 2–3 drivers named; (5) names the trap; (6) ends with a hypothesis that is a bet sized against the gap (not a list) and a first move. 4 = pass, 5 = clean first round, 6 = MBB-ready.';
function personaText(){return S.persona==='poker'?'PERSONA: POKER FACE. You are a terse MBB interviewer. Lead with the score, no praise, state what was missing in plain words, end with one pointed push-back question. Under 110 words. Still provide any JSON fields requested.':'PERSONA: FRIENDLY COACH. Warm and specific. Explain each rubric point in a phrase, quote the student\'s own words where useful, and always give a polished model answer. Under 220 words.';}
function stdText(t){return `GOLD-STANDARD GENERIC FRAMEWORK — ${t.name}\n${treeText(t)}\nMECE cut: ${t.cut}\nTrap: ${t.trap}\nStart bucket: ${t.start}${t.startWhy?' — '+t.startWhy:''}${t.hyp?'\nHypothesis starter: '+t.hyp:''}`;}
function caseText(c){return `CASE — ${c.title} (${c.client}, ${c.industry}, difficulty ${c.diff||2})\nPrompt: ${c.prompt}\nFacts available on request (give qualitatively unless an exhibit is shown):\n${(c.questions||[]).map(q=>'- '+q.q+' → '+q.a).join('\n')}\nModel tailored structure:\n${c.buckets.map((b,i)=>`${i+1}. ${b.name}: ${b.subs.join('; ')}`).join('\n')}\nHow it was tailored: ${c.tailored||''}\nModel hypothesis: ${c.hyp}\nTrap: ${c.trap}\nStart with: ${c.start} — ${c.startWhy||''}`;}
const COACHGAPS='Known gaps of this student (from coaching record): never names the case type first; hypothesis is a list of options rather than a bet; hypothesis not sized against the gap; generic buckets that could fit any company; profitability frame bolted onto a growth case; states an investment lean before the one-line math; mixes risks into the lean; says "I\'m blanking" instead of recovering.';
const SYS_GRADER=()=>`You are an expert case-interview coach for MBB recruiting at NYU Stern. ${personaText()}\n${RUBRIC}\n${COACHGAPS}\nAlways respond with JSON only when a JSON shape is requested.`;

/* ================= TIMER / MIC ================= */
let TM=null;function startTimer(sec,id,onEnd){stopTimer();let left=sec;const el=()=>document.getElementById(id);const paint=()=>{const e=el();if(!e)return;e.textContent=fmtTime(left);e.classList.toggle('warn',left<=15);};paint();TM=setInterval(()=>{left--;paint();if(left<=0){stopTimer();buzz([30,30,30]);onEnd&&onEnd();}},1000);}
function stopTimer(){if(TM){clearInterval(TM);TM=null;}}
let REC=null;function micToggle(taId,btnId){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('Dictation not supported in this browser');return;}const b=document.getElementById(btnId);if(REC){REC.stop();REC=null;b&&b.classList.remove('on');return;}REC=new SR();REC.continuous=true;REC.interimResults=false;REC.lang='en-US';REC.onresult=e=>{const ta=document.getElementById(taId);if(!ta)return;for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)ta.value+=(ta.value&&!/\s$/.test(ta.value)?' ':'')+e.results[i][0].transcript;};REC.onend=()=>{REC=null;b&&b.classList.remove('on');};REC.start();b&&b.classList.add('on');toast('Listening — tap again to stop');}
const micBtn=(ta,id)=>`<button class="mic" id="${id}" onclick="micToggle('${ta}','${id}')" title="Dictate"><svg class="ico" viewBox="0 0 24 24"><path d="M12 3a4 4 0 0 1 4 4v5a4 4 0 0 1-8 0V7a4 4 0 0 1 4-4z"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3"/></svg></button>`;
function needLive(){if(Live.on)return true;$('#view').innerHTML=`<div class="card"><h2 style="font-size:20px">Live mode needs a connection</h2><p class="sm mute">This mode asks Claude to grade and generate in real time. Two ways to get it:</p><p class="sm"><b>Claude-hosted app</b> — open the Claude artifact version signed in to your Claude account; grading draws on your plan, no extra cost.</p><p class="sm"><b>API key</b> — paste an Anthropic API key under Coach → Settings; billed per use by Anthropic.</p><button class="btn sec" onclick="go('coach')">Open settings</button><button class="btn ghost" onclick="go('live')">Back</button></div>`;return false;}
function score6HTML(n){return `<div class="score6">${[1,2,3,4,5,6].map(i=>`<i class="${i<=n?'on':''}"></i>`).join('')}</div>`;}
const RUBK=[['answers','Answers the question'],['mece','2–4 MECE buckets'],['industry','Smells like the industry'],['depth','One level down'],['trap','Names the trap'],['hyp','Hypothesis + first move']];
function rubricHTML(items){return `<div>${RUBK.map(([k,lab],i)=>{const it=(items||[]).find(x=>x.k===k)||items?.[i]||{};return `<div class="rub"><div class="m ${it.pass?'ok':'bad'}">${it.pass?'✓':'×'}</div><div><b>${lab}</b>${it.note?'<div class="mute">'+esc(it.note)+'</div>':''}</div></div>`;}).join('')}</div>`;}
function selectType(id,withRandom){return `<select class="in" id="${id}">${withRandom?'<option value="">Random type</option>':''}${TYPES.map(t=>`<option value="${t.id}">${esc(t.name)}${t.std?'':' (beyond the ten)'}</option>`).join('')}</select>`;}
function pickCase(tid,gen){const pool=allCases().filter(c=>!tid||c.type===tid);return rnd(pool);}

/* ================= STRUCTURE GRADING (shared) ================= */
async function gradeStructure(t,c,text,extra){const r=await Live.ask(`${stdText(t)}\n\n${c?caseText(c):'Prompt: '+t.prompt}\n\nThe student had 90 seconds and wrote this structure:\n"""${text}"""\n${extra||''}\nGrade it on the six-item rubric. Return JSON only:\n{"score":0-6,"items":[{"k":"answers","pass":bool,"note":"<=14 words"},{"k":"mece","pass":bool,"note":""},{"k":"industry","pass":bool,"note":""},{"k":"depth","pass":bool,"note":""},{"k":"trap","pass":bool,"note":""},{"k":"hyp","pass":bool,"note":""}],"feedback":"persona voice, see persona rules","model":"a polished 30-second model structure for THIS client in 4-7 short lines, buckets renamed as questions about the client"}`,{system:SYS_GRADER(),json:true});
 (r.items||[]).forEach(it=>rubricMark(it.k,!!it.pass));return r;}
function structureResultHTML(r,xp){return `<div class="fb ${r.score>=4?'ok':'bad'} pop"><h3>${r.score}/6 — ${r.score>=6?'MBB-ready':r.score>=5?'Clean first round':r.score>=4?'Pass':'Below the bar'}</h3>${xp?`<div class="xp">+${xp} XP</div>`:''}${score6HTML(r.score)}${rubricHTML(r.items)}<div class="tip"><b>${S.persona==='poker'?'Interviewer':'Coach'}</b>${esc(r.feedback||'')}</div>${r.model?`<div class="tip"><b>Model answer</b>${esc(r.model)}</div>`:''}</div>`;}

/* ================= LIVE CASE ================= */
let LC=null;
const PHASES=['Setup','Prompt & clarify','Structure','Exhibit','Brainstorm','Recommendation','Scorecard'];
function liveCaseSetup(){if(!needLive())return;LC={phase:0};$('#view').innerHTML=`<div class="fam-live"><button class="btn ghost" style="justify-content:flex-start;padding:0 0 10px" onclick="go('live')">← Live</button><div class="card"><span class="tag fam">Live case</span><h2 style="font-size:22px;margin:8px 0 4px">Claude runs the case</h2><p class="sm mute">Candidate-led, the casebook way: you get the prompt only, clarifying answers are directional, numbers wait for the exhibit. Structure is graded 0–6; the whole case is scored and logged.</p>
 <div class="sect">Case type</div>${selectType('lc-type',true)}
 <div class="sect">Source</div><div class="pills" id="lc-src"><button class="on" onclick="pillSel('lc-src',this)" data-v="lib">From the library</button><button onclick="pillSel('lc-src',this)" data-v="gen">Generate a new one</button>${S.gen.length?`<button onclick="pillSel('lc-src',this)" data-v="mine">My generated (${S.gen.length})</button>`:''}</div>
 <div class="sect">Interviewer</div><div class="pills" id="lc-per"><button class="${S.persona==='coach'?'on':''}" onclick="pillSel('lc-per',this);S.persona='coach';save()" data-v="coach">Friendly Coach</button><button class="${S.persona==='poker'?'on':''}" onclick="pillSel('lc-per',this);S.persona='poker';save()" data-v="poker">Poker Face</button></div>
 <button class="btn live" onclick="liveCaseBegin()">Start the case</button></div></div>`;}
function pillSel(gid,btn){document.querySelectorAll('#'+gid+' button').forEach(b=>b.classList.remove('on'));btn.classList.add('on');}
function pillVal(gid){const b=document.querySelector('#'+gid+' button.on');return b?b.dataset.v:null;}
async function liveCaseBegin(){const tid=$('#lc-type').value||rnd(TYPES.slice(0,10)).id;const src=pillVal('lc-src');const t=T(tid);let c;
 if(src==='gen'){c=await genScenario(tid);if(!c)return;}else if(src==='mine'){const m=S.gen.filter(x=>x.type===tid);c=m.length?rnd(m):rnd(S.gen);}else c=pickCase(tid);
 LC={phase:1,t:T(c.type),c,clar:[],scores:{},transcript:[],started:now(),exhibits:[],brain:null};renderLiveCase();}
function phaseBar(){return `<div class="phase">${PHASES.slice(1).map((p,i)=>`<i class="${i+1<LC.phase?'on':i+1===LC.phase?'cur':''}"></i>`).join('')}</div><div class="xs mute b">${esc(LC.c.client)} · ${PHASES[LC.phase]}</div>`;}
function renderLiveCase(){const c=LC.c,t=LC.t;let h=`<div class="fam-live"><div class="playhead"><button class="ghost" onclick="quit()" style="color:var(--mute);font-size:22px;line-height:1">×</button><div class="grow1">${phaseBar()}</div></div>`;
 if(LC.phase===1){h+=`<div class="chat" id="chat"><div class="msg ai">${esc(c.prompt)}</div>${LC.clar.map(x=>`<div class="msg me">${esc(x.q)}</div><div class="msg ai">${esc(x.a)}</div>`).join('')}</div>`;
  if(LC.clar.length<4)h+=`<div class="row"><input class="in" id="lc-q" placeholder="Ask a clarifying question (${4-LC.clar.length} left)…" onkeydown="if(event.key==='Enter')liveAsk()"><button class="btn sm" style="margin:0" onclick="liveAsk()">Ask</button></div>`;
  h+=`<button class="btn live" onclick="LC.phase=2;renderLiveCase()">I'm ready to structure (90 s)</button>`;}
 else if(LC.phase===2){h+=`<div class="card"><div class="sm mute">${esc(c.prompt)}</div>${LC.clar.length?`<div class="xs mute" style="margin-top:6px">${LC.clar.map(x=>'Q: '+esc(x.q)+' — '+esc(x.a)).join('<br>')}</div>`:''}</div><div class="timer" id="lc-timer">1:30</div><div class="row" style="align-items:flex-start"><textarea class="ans grow1" id="lc-struct" placeholder="Name the type → size the gap → hypothesis → buckets with click-downs → where you start. One idea per line."></textarea>${micBtn('lc-struct','lc-mic')}</div><button class="btn live" id="lc-submit" onclick="liveStructure()">Present it</button><div id="lc-fb"></div>`;
  setTimeout(()=>startTimer(90,'lc-timer',()=>toast('Time — present what you have')),50);}
 else if(LC.phase===3){const ex=LC.exhibits[LC.exhibits.length-1];if(!ex)h+=`<div class="card">${thinking('Preparing an exhibit')}</div>`;else{h+=`<div class="card"><div class="sm" style="margin-bottom:6px">${esc(ex.intro||'')}</div><h3 style="font-size:16px">${esc(ex.title)}</h3>${exhibitTable(ex)}<div class="sm b" style="margin-top:8px">${esc(ex.question)}</div></div>`;if(!ex.grade)h+=`<div class="hint">Say what you see first, then the approach, then the math, then the so-what.</div><div class="row" style="align-items:flex-start"><textarea class="ans grow1" id="lc-ex" placeholder="Eyeball insight → approach → calculation → so-what for the client"></textarea>${micBtn('lc-ex','lc-mic2')}</div><button class="btn live" id="lc-exsub" onclick="liveExhibit()">Submit</button><div id="lc-fb"></div>`;else h+=exhibitResultHTML(ex.grade)+`<button class="btn live" onclick="LC.phase=4;renderLiveCase()">Next: brainstorm</button>`;}}
 else if(LC.phase===4){if(!LC.brain)h+=`<div class="card">${thinking('Writing the brainstorm question')}</div>`;else{h+=`<div class="card"><div class="msg ai" style="max-width:100%">${esc(LC.brain.prompt)}</div></div>`;if(!LC.brain.grade){h+=`<div class="timer" id="lc-timer">0:30</div><div class="row" style="align-items:flex-start"><textarea class="ans grow1" id="lc-brain" placeholder="Headers first, 2–3 ideas each, finish with 'I'd start with…'"></textarea>${micBtn('lc-brain','lc-mic3')}</div><button class="btn live" id="lc-brsub" onclick="liveBrainstorm()">Answer</button><div id="lc-fb"></div>`;setTimeout(()=>startTimer(30,'lc-timer',()=>toast('Time — answer now')),50);}else h+=brainResultHTML(LC.brain.grade)+`<button class="btn live" onclick="LC.phase=5;renderLiveCase()">Next: recommendation</button>`;}}
 else if(LC.phase===5){h+=`<div class="card"><div class="msg ai" style="max-width:100%">The CEO just walked in and has two minutes. What do you tell them?</div></div><div class="hint">Recommendation first, then risks, then next steps. Answer the question that was asked, in the client's units.</div><div class="row" style="align-items:flex-start"><textarea class="ans grow1" id="lc-rec" placeholder="Recommendation → risks → next steps"></textarea>${micBtn('lc-rec','lc-mic4')}</div><button class="btn live" id="lc-recsub" onclick="liveRec()">Deliver</button><div id="lc-fb"></div>`;}
 else if(LC.phase===6){const s=LC.scores;const total=Math.round(((s.structure||0)/6*40)+((s.exhibit||0)/6*20)+((s.brain||0)/6*15)+((s.rec||0)/10*25));h+=`<div class="card" style="text-align:center"><div class="xs mute b">${esc(c.client)} · ${esc(t.name)}</div><div class="big" style="margin:8px 0">${total}</div><div class="sm mute">out of 100</div><div class="stat" style="margin-top:12px"><div><b>${s.structure??'–'}/6</b><small>structure</small></div><div><b>${s.exhibit??'–'}/6</b><small>exhibit</small></div><div><b>${s.brain??'–'}/6</b><small>brainstorm</small></div><div><b>${s.rec??'–'}/10</b><small>recommendation</small></div><div><b>${LC.clar.length}</b><small>clarifiers</small></div><div><b>+${LC.xp||0}</b><small>XP</small></div></div></div>${LC.summary?`<div class="card"><h3 style="font-size:16px;margin-bottom:6px">Debrief</h3><div class="sm">${esc(LC.summary)}</div></div>`:''}<button class="btn live" onclick="liveCaseSetup()">Another case</button><button class="btn sec" onclick="go('live')">Done</button>`;}
 h+='</div>';$('#view').innerHTML=h;window.scrollTo(0,0);if(LC.phase===3&&!LC.exhibits.length)liveMakeExhibit();if(LC.phase===4&&!LC.brain)liveMakeBrain();}
async function liveAsk(){const q=$('#lc-q').value.trim();if(!q)return;$('#lc-q').disabled=true;const chat=$('#chat');chat.insertAdjacentHTML('beforeend',`<div class="msg me">${esc(q)}</div><div class="msg ai" id="lc-wait">${thinking()}</div>`);
 try{const a=await Live.ask(`${caseText(LC.c)}\n\nYou are the interviewer. The candidate asks a clarifying question. Answer in character in one or two sentences, qualitative and directional only — hold numbers for the exhibits unless the question is the quantified goal or timeline, which you give. If the fact is not in the case, say you don't have that detail and that they should assume whatever is reasonable. Do not coach.\nPrevious questions: ${LC.clar.map(x=>x.q).join(' | ')||'none'}\nQuestion: "${q}"`,{system:'You are a strict but fair MBB case interviewer. Reply with the answer only, no preamble.',tier:'quick'});LC.clar.push({q,a:a.trim()});}catch(e){toast(Live.errMsg(e));}renderLiveCase();}
async function liveStructure(){const text=$('#lc-struct').value.trim();if(!text)return;stopTimer();$('#lc-submit').classList.add('hide');$('#lc-struct').disabled=true;$('#lc-fb').innerHTML=`<div class="fb neutral">${thinking('Grading your structure')}</div>`;
 try{const r=await gradeStructure(LC.t,LC.c,text);LC.scores.structure=r.score;LC.structure=text;const xp=award(r.score*15,false);LC.xp=(LC.xp||0)+xp;logEvent({k:'live-structure',t:LC.t.id,score:r.score,items:(r.items||[]).map(i=>i.k+':'+(i.pass?1:0)).join(',')});$('#lc-fb').innerHTML=structureResultHTML(r,xp)+`<button class="btn live" onclick="LC.phase=3;renderLiveCase()">Next: exhibit</button>`;}catch(e){$('#lc-fb').innerHTML=`<div class="fb bad">${esc(Live.errMsg(e))}</div><button class="btn sec" onclick="$('#lc-submit').classList.remove('hide');$('#lc-struct').disabled=false;$('#lc-fb').innerHTML=''">Try again</button>`;}}
function exhibitTable(ex){return `<table class="ex"><thead><tr>${ex.columns.map((c,i)=>`<th class="${i?'num':''}">${esc(c)}</th>`).join('')}</tr></thead><tbody>${ex.rows.map(r=>`<tr>${r.map((v,i)=>`<td class="${i?'num':''}">${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
async function liveMakeExhibit(){try{const ex=await Live.ask(`${caseText(LC.c)}\n\nThe candidate's structure was:\n"""${LC.structure||''}"""\nWrite ONE exhibit the interviewer would now hand over, consistent with the case facts, that tests the bucket the candidate should start with. 4–6 rows, 3–5 columns, numbers that work by hand and hide one insight that needs a quick calculation (a mix shift, a per-unit figure, a breakeven). Return JSON only: {"title":"","intro":"one sentence in the interviewer's voice","columns":["label","..."],"rows":[["",""]],"question":"what the interviewer asks","key":{"insight":"the eyeball insight","calc":"the calculation and result","soWhat":"the implication for the client"}}`,{system:'You write realistic, internally consistent case-interview exhibits.',json:true});LC.exhibits.push(ex);}catch(e){toast(Live.errMsg(e));LC.phase=4;}renderLiveCase();}
async function liveExhibit(){const text=$('#lc-ex').value.trim();if(!text)return;$('#lc-exsub').classList.add('hide');$('#lc-ex').disabled=true;$('#lc-fb').innerHTML=`<div class="fb neutral">${thinking('Checking the math')}</div>`;const ex=LC.exhibits[LC.exhibits.length-1];
 try{const r=await Live.ask(`${caseText(LC.c)}\n\nExhibit "${ex.title}": columns ${JSON.stringify(ex.columns)}, rows ${JSON.stringify(ex.rows)}. Question: ${ex.question}\nKey: insight = ${ex.key.insight}; calc = ${ex.key.calc}; so-what = ${ex.key.soWhat}\n\nCandidate's answer:\n"""${text}"""\nScore on BCG's three exhibit criteria, 0–2 each. Return JSON only: {"mechanics":0-2,"direction":0-2,"insight":0-2,"feedback":"persona voice","model":"the ideal 4-sentence answer: what I see, approach, number, so-what"}`,{system:SYS_GRADER(),json:true});ex.grade=r;const sc=(r.mechanics||0)+(r.direction||0)+(r.insight||0);LC.scores.exhibit=sc;const xp=award(sc*10,false);LC.xp=(LC.xp||0)+xp;r.xp=xp;logEvent({k:'live-exhibit',t:LC.t.id,score:sc});renderLiveCase();}catch(e){$('#lc-fb').innerHTML=`<div class="fb bad">${esc(Live.errMsg(e))}</div>`;}}
function exhibitResultHTML(r){const sc=(r.mechanics||0)+(r.direction||0)+(r.insight||0);return `<div class="fb ${sc>=4?'ok':'bad'} pop"><h3>${sc}/6</h3>${r.xp?`<div class="xp">+${r.xp} XP</div>`:''}<div class="stat" style="margin:8px 0"><div><b>${r.mechanics}/2</b><small>mechanics</small></div><div><b>${r.direction}/2</b><small>direction</small></div><div><b>${r.insight}/2</b><small>so-what</small></div></div><div class="tip"><b>${S.persona==='poker'?'Interviewer':'Coach'}</b>${esc(r.feedback||'')}</div>${r.model?`<div class="tip"><b>Model answer</b>${esc(r.model)}</div>`:''}</div>`;}
async function liveMakeBrain(){try{const r=await Live.ask(`${caseText(LC.c)}\nWhat has happened so far: structure presented${LC.exhibits[0]?'; exhibit "'+LC.exhibits[0].title+'" shown, key insight: '+LC.exhibits[0].key.insight:''}.\nWrite the brainstorm question the interviewer would ask next, in the interviewer's voice, two or three sentences, mid-case, referencing what has been learned ("Given that X, what are some ways the client could Y?"). Return JSON only: {"prompt":"","lens":"the simplest lens that structures it (e.g. Internal vs External, Value chain, Customer journey, Fixed vs Variable)","model":[{"bucket":"","ideas":["","",""]}]}`,{system:'You write mid-case brainstorm prompts for case interviews.',json:true});LC.brain=r;}catch(e){toast(Live.errMsg(e));LC.phase=5;}renderLiveCase();}
async function liveBrainstorm(){const text=$('#lc-brain').value.trim();if(!text)return;stopTimer();$('#lc-brsub').classList.add('hide');$('#lc-brain').disabled=true;$('#lc-fb').innerHTML=`<div class="fb neutral">${thinking('Scoring')}</div>`;
 try{const r=await gradeBrain(LC.brain.prompt,text,LC.brain,caseText(LC.c));LC.brain.grade=r;const sc=(r.structure||0)+(r.specificity||0)+(r.soWhat||0);LC.scores.brain=sc;const xp=award(sc*10,false);LC.xp=(LC.xp||0)+xp;r.xp=xp;logEvent({k:'live-brain',t:LC.t.id,score:sc});renderLiveCase();}catch(e){$('#lc-fb').innerHTML=`<div class="fb bad">${esc(Live.errMsg(e))}</div>`;}}
async function gradeBrain(prompt,text,key,ctx){return Live.ask(`${ctx||''}\nBrainstorm question: ${prompt}\nModel (for reference): lens ${key.lens||key.why||''}; ${JSON.stringify(key.model||[])}\n\nCandidate answered on the spot (30 seconds):\n"""${text}"""\nScore 0–2 each: structure (named a simple lens and gave headers first), specificity (ideas are concrete and tailored to this client), soWhat (second-order implications or a closing priority "I'd start with…"). Return JSON only: {"structure":0-2,"specificity":0-2,"soWhat":0-2,"feedback":"persona voice","model":"3-5 lines: lens, two or three ideas per header, closing priority"}`,{system:SYS_GRADER(),json:true});}
function brainResultHTML(r){const sc=(r.structure||0)+(r.specificity||0)+(r.soWhat||0);return `<div class="fb ${sc>=4?'ok':'bad'} pop"><h3>${sc}/6</h3>${r.xp?`<div class="xp">+${r.xp} XP</div>`:''}<div class="stat" style="margin:8px 0"><div><b>${r.structure}/2</b><small>structure</small></div><div><b>${r.specificity}/2</b><small>specific</small></div><div><b>${r.soWhat}/2</b><small>so-what</small></div></div><div class="tip"><b>${S.persona==='poker'?'Interviewer':'Coach'}</b>${esc(r.feedback||'')}</div>${r.model?`<div class="tip"><b>Model answer</b>${esc(r.model)}</div>`:''}</div>`;}
async function liveRec(){const text=$('#lc-rec').value.trim();if(!text)return;$('#lc-recsub').classList.add('hide');$('#lc-rec').disabled=true;$('#lc-fb').innerHTML=`<div class="fb neutral">${thinking('Scoring the close')}</div>`;
 try{const r=await Live.ask(`${caseText(LC.c)}\nWhat the candidate has: structure score ${LC.scores.structure}/6${LC.exhibits[0]?'; exhibit insight: '+LC.exhibits[0].key.insight+'; '+LC.exhibits[0].key.soWhat:''}${LC.brain?'; brainstorm on: '+LC.brain.prompt:''}.\n\nCandidate's closing to the CEO:\n"""${text}"""\nScore 0–10: answers the question asked in the client's units, leads with the recommendation, states 2–3 risks separately, concrete next steps, uses the numbers learned. Then write a two-sentence debrief of the whole case: the single biggest thing to fix next time, and what was strong. Return JSON only: {"score":0-10,"feedback":"persona voice","model":"a 5-line model close","debrief":""}`,{system:SYS_GRADER(),json:true});LC.scores.rec=r.score;LC.summary=r.debrief;const xp=award((r.score||0)*5+100,false);LC.xp=(LC.xp||0)+xp;logEvent({k:'live-case',t:LC.t.id,c:LC.c.client,s:LC.scores,xp});const b=badge('first-live','First live case','Completed a full live case');if(b)toast('Badge: First live case');confetti(120,'#0EA5A4');$('#lc-fb').innerHTML=`<div class="fb ${r.score>=6?'ok':'bad'} pop"><h3>${r.score}/10</h3><div class="xp">+${xp} XP</div><div class="tip"><b>${S.persona==='poker'?'Interviewer':'Coach'}</b>${esc(r.feedback||'')}</div>${r.model?`<div class="tip"><b>Model close</b>${esc(r.model)}</div>`:''}</div><button class="btn live" onclick="LC.phase=6;renderLiveCase()">Scorecard</button>`;}catch(e){$('#lc-fb').innerHTML=`<div class="fb bad">${esc(Live.errMsg(e))}</div>`;}}

