/* ================= SCENARIO GENERATOR ================= */
async function genScenario(tid,silent){if(!Live.on){toast('Generating needs a live connection');return null;}const t=T(tid);const names=allCases().map(c=>c.client).slice(-200);if(!silent)$('#view').innerHTML=`<div class="card">${thinking('Writing a new '+t.name+' case')}</div>`;
 try{const c=await Live.ask(`${stdText(t)}\n\nWrite ONE new practice case of this type for an MBA case-interview drill. Standard: realistic and context-rich — a named fictional client in a specific real place, with size (units, revenue, staff), how it makes money, what changed, who is asking, and a quantified goal with a timeline. Never a generic "the manufacturer". Vary industry; do not default to public sector. Do NOT use any of these client names: ${names.join(', ')}.\nReturn JSON only, exactly this shape: {"title":"two-word case title","client":"","industry":"","diff":1-4,"prompt":"3-5 sentences in the interviewer's voice","questions":[{"q":"a clarifying question a good candidate would ask","a":"the qualitative answer"} x5],"buckets":[{"name":"bucket renamed in the industry's own words","subs":["","",""]} x3-4 following the gold-standard structure],"generic":"${t.name}","tailored":"one sentence on how the generic frame was tailored","hyp":"a hypothesis that is a bet sized against the gap","trap":"","start":"the name of one of the buckets above","startWhy":""}`,{system:'You write realistic, internally consistent case-interview practice cases. JSON only.',json:true});
  if(!c||!c.prompt||!Array.isArray(c.buckets)||!c.buckets.length)throw{message:'Malformed case'};c.type=tid;c.id='gen-'+Date.now();c.gen=true;c.diff=c.diff||2;if(!c.buckets.some(b=>b.name===c.start))c.start=c.buckets[0].name;S.gen.push(c);if(S.gen.length>80)S.gen=S.gen.slice(-80);save();const b=badge('gen1','Case writer','Generated a new scenario');if(b)toast('Badge: Case writer');return c;}catch(e){toast('Could not generate: '+Live.errMsg(e));if(!silent)go('drills');return null;}}
async function genAndShow(){const tid=$('#gen-type').value||rnd(TYPES).id;const c=await genScenario(tid);if(!c)return;toast('Saved to Library → Cases');go('library','cases');}

