function clarifyBegin(){const c=pickCase($('#cl-type').value||null);DR={c,t:T(c.type)};$('#view').innerHTML=`<div class="fam-eval"><div class="playhead"><button class="ghost" onclick="go('drills')" style="color:var(--mute);font-size:22px;line-height:1">×</button><div class="grow1 xs mute b">Clarifying · ${esc(c.client)}</div></div><div class="card"><div class="msg ai" style="max-width:100%">${esc(c.prompt)}</div></div><textarea class="ans" id="cl-text" placeholder="Three questions, one per line — and say what each one would change about your structure"></textarea><button class="btn" id="cl-sub" onclick="clarifySubmit()">Check</button><div id="cl-fb"></div></div>`;}
