 if(Live.on){$('#sy-fb').innerHTML=`<div class="fb neutral">${thinking('Scoring the close')}</div>`;try{const r=await Live.ask(`${caseText(c)}\nAssume the model hypothesis held. The candidate's close to the CEO:\n"""${text}"""\nScore 0–10: leads with the recommendation that answers the question asked in the client's units (4), risks stated separately and specific (3), concrete next steps (3). Return JSON only: {"score":0-10,"feedback":"persona voice","model":"a 5-line model close"}`,{system:SYS_GRADER(),json:true});const xp=award((r.score||0)*5,false);logEvent({k:'synth',t:DR.t.id,score:r.score});$('#sy-fb').innerHTML=`<div class="fb ${r.score>=6?'ok':'bad'} pop"><h3>${r.score}/10</h3><div class="xp">+${xp} XP</div><div class="tip"><b>Coach</b>${esc(r.feedback||'')}</div>${r.model?`<div class="tip"><b>Model close</b>${esc(r.model)}</div>`:''}</div><button class="btn" onclick="hypSetup()">Another case</button>`;return;}catch(e){toast(Live.errMsg(e));}}
