/* ================= MENTAL MATH ================= */
function mmGen(){const r=(a,b)=>a+Math.floor(Math.random()*(b-a+1));const kinds=['pct','mult','growth','be','margin','df','ann','size','chg','div'];const k=rnd(kinds);let q,a,u='';
 if(k==='pct'){const p=rnd([5,8,12,15,18,22,25,30,35,40,45,60,65,75]);const n=rnd([120,240,360,480,640,750,840,960,1200,1800,2400,3600]);q=`${p}% of ${n.toLocaleString()}`;a=p*n/100;}
 else if(k==='mult'){const x=r(12,98),y=rnd([15,25,35,45,120,150,250,350,450,1200,1500,2500]);q=`${x} × ${y.toLocaleString()}`;a=x*y;}
 else if(k==='growth'){const n=rnd([3,4,5,6,8,10]);const m=rnd([2,2,3]);q=`Approx. annual growth rate to ${m===2?'double':'triple'} in ${n} years (%)`;a=(m===2?72:114)/n;u='%';}
 else if(k==='be'){const f=rnd([120,200,300,450,600,800])*1000;const p=rnd([20,25,40,50,60,80]);const vc=Math.round(p*rnd([.4,.5,.6]));q=`Breakeven units: fixed cost $${(f/1000).toLocaleString()}K, price $${p}, variable cost $${vc}`;a=f/(p-vc);}
 else if(k==='margin'){const rev=rnd([2.4,3.6,4.8,6,7.5,9,12,15,18,24]);const m=rnd([8,12,15,20,25,30,35,40]);q=`Operating profit at ${m}% margin on $${rev}M revenue ($M)`;a=rev*m/100;}
 else if(k==='df'){const y=rnd([1,2,3,5]);const rate=10;const table={1:.91,2:.83,3:.75,5:.62};const cf=rnd([10,20,30,40,50,80,100]);q=`PV of $${cf}M received in year ${y} at 10% ($M, use 0.91/0.83/0.75/0.62)`;a=cf*table[y];}
 else if(k==='ann'){const cf=rnd([10,15,20,25,30,40,50]);const n=rnd([3,5,10]);const af={3:2.49,5:3.79,10:6.14};q=`PV of $${cf}M a year for ${n} years at 10% ($M, annuity factor ${af[n]})`;a=cf*af[n];}
 else if(k==='size'){const pop=rnd([130,340,50,20,8]);const unit=pop===340?'M people':pop===130?'M households':'M people';const pen=rnd([5,10,15,20,25,40,60]);const freq=rnd([1,2,4,6,12]);const price=rnd([5,10,20,25,40,50,100]);q=`Market: ${pop}${unit} × ${pen}% penetration × ${freq}/yr × $${price} ($M)`;a=pop*pen/100*freq*price;}
 else if(k==='chg'){const x=rnd([80,120,150,200,240,320,400,450,600]);const y=Math.round(x*rnd([.85,.9,.92,.95,1.05,1.08,1.12,1.15,1.2,1.25,1.3]));q=`% change from ${x} to ${y}`;a=(y-x)/x*100;u='%';}
 else{const n=rnd([1800,2400,3600,4200,5400,7200,8400,9600,12000]);const d=rnd([12,15,16,18,24,25,30,32,36,40,45,48]);q=`${n.toLocaleString()} ÷ ${d}`;a=n/d;}
 return{q,a,u};}
let MM=null;
function mathStart(){MM={qs:Array.from({length:10},mmGen),i:0,ok:0,t0:now()};mathRender();}
function mathRender(){const q=MM.qs[MM.i];$('#view').innerHTML=`<div class="fam-ops"><div class="playhead"><button class="ghost" onclick="go('drills')" style="color:var(--mute);font-size:22px;line-height:1">×</button><div class="prog"><i style="width:${MM.i/10*100}%"></i></div><span class="combo">${MM.ok}/${MM.i}</span></div><div class="xs mute b">Mental math · ${MM.i+1}/10 · within 3% counts</div><div class="q" style="font-size:22px">${esc(q.q)}</div><div class="row"><input class="in" id="mm-in" inputmode="decimal" placeholder="Answer${q.u?' ('+q.u+')':''}" onkeydown="if(event.key==='Enter')mathAnswer()" autocomplete="off"><button class="btn sm" style="margin:0" onclick="mathAnswer()">Go</button></div><div id="mm-fb"></div></div>`;setTimeout(()=>{const i=$('#mm-in');i&&i.focus();},50);MM.t=now();}
function mathAnswer(){const q=MM.qs[MM.i];const raw=$('#mm-in').value.replace(/[,$%]/g,'').trim();if(!raw)return;const v=parseFloat(raw);const ok=Math.abs(v-q.a)<=Math.max(Math.abs(q.a)*0.03,0.01);const fast=(now()-MM.t)/1000<10;if(ok){MM.ok++;S.combo++;}else S.combo=0;const xp=ok?award(8,fast):0;$('#mm-in').disabled=true;const shown=Math.abs(q.a)>=100?Math.round(q.a).toLocaleString():(+q.a.toFixed(2)).toString();$('#mm-fb').innerHTML=`<div class="fb ${ok?'ok':'bad'} pop"><h3>${ok?'Yes':'Not quite'} — ${shown}${q.u||''}</h3>${xp?`<div class="xp">+${xp} XP${fast?' · speed':''}</div>`:''}</div><button class="btn" onclick="mathNext()">${MM.i<9?'Next':'Finish'}</button>`;if(ok)buzz([10,30,10]);}
function mathNext(){MM.i++;if(MM.i<10)mathRender();else{const sec=Math.round((now()-MM.t0)/1000);logEvent({k:'math',ok:MM.ok,n:10,sec});if(MM.ok===10){const b=badge('math10','Calculator','10/10 on a mental-math set');if(b)confetti(100);}$('#view').innerHTML=`<div class="card" style="text-align:center"><div class="xs mute b">Mental math</div><div class="big" style="margin:8px 0">${MM.ok}/10</div><div class="sm mute">${fmtTime(sec)} · ${MM.ok===10?'Perfect.':MM.ok>=8?'Sharp.':'Keep the reps up.'}</div></div><button class="btn" onclick="mathStart()">Another set</button><button class="btn sec" onclick="go('drills')">Done</button>`;save();renderTop();}}

