function go(v,arg){stopTimer();V=v;VA=arg;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('on',b.id==='nav-'+({level:'home',play:'home'}[v]||v)));renderTop();({home,level,play:renderPlay,live,drills,library,coach})[v](arg);window.scrollTo(0,0);}
