const IC={case:'<path d="M4 7h16v12H4z"/><path d="M9 7V5h6v2M4 12h16"/>',recite:'<circle cx="12" cy="13" r="8"/><path d="M12 9v4l2.5 2M10 2h4"/>',brain:'<path d="M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.6.5 1 1.2 1.1 2h4.8c.1-.8.5-1.5 1.1-2A6 6 0 0 0 12 3z"/>',ex:'<path d="M4 20V10M10 20V4M16 20v-8M22 20H2"/>',clar:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9.5a2.5 2.5 0 1 1 3.5 2.3c-.7.3-1 .9-1 1.7M12 17h.01"/>',hyp:'<path d="M12 3v6M9 6l3 3 3-3"/><path d="M5 21a7 7 0 0 1 14 0"/>',math:'<path d="M5 5h14v14H5z"/><path d="M8 9h8M12 7v4M8 15h8"/>',num:'<path d="M4 7h16M4 12h16M4 17h10"/>',gen:'<path d="M12 3v3M12 18v3M3 12h3M18 12h3M5.6 5.6l2.1 2.1M16.3 16.3l2.1 2.1M5.6 18.4l2.1-2.1M16.3 7.7l2.1-2.1"/>',rev:'<path d="M3 12a9 9 0 1 0 3-6.7"/><path d="M3 4v5h5"/>'};
